CREATE FUNCTION public.increment_visitors() RETURNS bigint
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE public.site_stats
  SET value = value + 1
  WHERE key = 'total_visitors'
  RETURNING value;
$$;


